Para resolver este problema de forma eficiente, podemos utilizar uma **Segment Tree** (Árvore de Segmentos).

### Ideia da Solução:
Para cada nó da árvore representando um intervalo contíguo, mantemos:
1. `ans`: o número de subsequências candidatas ($\gcd > 1$) contidas totalmente neste nó.
2. `pref`: uma lista compactada de prefixos do intervalo agrupados por seu $\gcd$, onde cada elemento armazena o valor do $\gcd$ e a quantidade de prefixos que compartilham esse mesmo valor.
3. `suff`: similarmente, uma lista compactada de sufixos agrupados por seu $\gcd$, ordenada a partir do final do intervalo em direção ao início.

Como o $\gcd$ de um prefixo (ou sufixo) estendido só pode se manter ou decrescer dividindo o valor anterior por pelo menos 2, o número de valores distintos de $\gcd$ em qualquer prefixo ou sufixo é no máximo $\approx 30$ (pois $S_i \le 10^9 < 2^{30}$).

Ao mesclar dois nós filhos $L$ e $R$:
- `ans = L.ans + R.ans + cross`, onde `cross` é o número de pares formados por um sufixo de $L$ e um prefixo de $R$ tais que o $\gcd$ combinado seja maior que 1.
- Como os $\gcd$s dos sufixos de $L$ e dos prefixos de $R$ formam cadeias de divisibilidade estritas à medida que se afastam da fronteira de junção, se $\gcd(L.suff[i].g, R.pref[j].g) = 1$, então para todo $j' \ge j$ o $\gcd$ também será 1 (podemos interromper o laço interno). Se isso ocorrer já em $j = 0$, para todo $i' \ge i$ também será 1 (podemos interromper o laço externo). Essa poda reduz drasticamente as chamadas da função $\gcd$, garantindo altíssimo desempenho.

### Código em Java:

```java
import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;

public class Main {

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            return hasNextByte() ? buffer[ptr++] : -1;
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = readByte();
            }
            int res = 0;
            while (c > ' ') {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + (c - '0');
                }
                c = readByte();
            }
            return res;
        }
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static class Node {
        long ans;
        // Prefixos e sufixos compactados: máximo 32 elementos
        int[] p_g;
        int[] p_c;
        int p_sz;

        int[] s_g;
        int[] s_c;
        int s_sz;

        Node() {
            p_g = new int[32];
            p_c = new int[32];
            s_g = new int[32];
            s_c = new int[32];
            p_sz = 0;
            s_sz = 0;
            ans = 0;
        }

        void setLeaf(int val) {
            ans = (val > 1) ? 1 : 0;
            p_g[0] = val;
            p_c[0] = 1;
            p_sz = 1;
            s_g[0] = val;
            s_c[0] = 1;
            s_sz = 1;
        }
    }

    static int N, M;
    static int[] S;
    static Node[] tree;

    static Node merge(Node L, Node R, Node res) {
        if (L == null) return R;
        if (R == null) return L;
        if (res == null) res = new Node();

        long cross = 0;
        // L.suff vai do final de L para o início
        // R.pref vai do início de R para o final
        for (int i = 0; i < L.s_sz; i++) {
            int gL = L.s_g[i];
            long cL = L.s_c[i];
            if (gcd(gL, R.p_g[0]) == 1) {
                // Se com o primeiro elemento de R já é 1, para todos os próximos de R será 1,
                // e para todos os próximos de L (que dividem gL) também será 1.
                break;
            }
            for (int j = 0; j < R.p_sz; j++) {
                if (gcd(gL, R.p_g[j]) > 1) {
                    cross += cL * R.p_c[j];
                } else {
                    // Como os próximos R.p_g dividem R.p_g[j], o gcd continuará sendo 1
                    break;
                }
            }
        }

        res.ans = L.ans + R.ans + cross;

        // Construir prefixos de res
        int psz = 0;
        for (int i = 0; i < L.p_sz; i++) {
            res.p_g[psz] = L.p_g[i];
            res.p_c[psz] = L.p_c[i];
            psz++;
        }
        int curG = L.p_g[L.p_sz - 1]; // gcd de todo o intervalo L
        for (int i = 0; i < R.p_sz; i++) {
            int g = gcd(curG, R.p_g[i]);
            if (g == res.p_g[psz - 1]) {
                res.p_c[psz - 1] += R.p_c[i];
            } else {
                res.p_g[psz] = g;
                res.p_c[psz] = R.p_c[i];
                psz++;
            }
        }
        res.p_sz = psz;

        // Construir sufixos de res
        int ssz = 0;
        for (int i = 0; i < R.s_sz; i++) {
            res.s_g[ssz] = R.s_g[i];
            res.s_c[ssz] = R.s_c[i];
            ssz++;
        }
        curG = R.s_g[R.s_sz - 1]; // gcd de todo o intervalo R
        for (int i = 0; i < L.s_sz; i++) {
            int g = gcd(curG, L.s_g[i]);
            if (g == res.s_g[ssz - 1]) {
                res.s_c[ssz - 1] += L.s_c[i];
            } else {
                res.s_g[ssz] = g;
                res.s_c[ssz] = L.s_c[i];
                ssz++;
            }
        }
        res.s_sz = ssz;

        return res;
    }

    static void build(int node, int l, int r) {
        if (l == r) {
            tree[node].setLeaf(S[l]);
            return;
        }
        int mid = (l + r) >> 1;
        build(node << 1, l, mid);
        build((node << 1) | 1, mid + 1, r);
        merge(tree[node << 1], tree[(node << 1) | 1], tree[node]);
    }

    static void update(int node, int l, int r, int idx, int val) {
        if (l == r) {
            tree[node].setLeaf(val);
            return;
        }
        int mid = (l + r) >> 1;
        if (idx <= mid) {
            update(node << 1, l, mid, idx, val);
        } else {
            update((node << 1) | 1, mid + 1, r, idx, val);
        }
        merge(tree[node << 1], tree[(node << 1) | 1], tree[node]);
    }

    static Node query(int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) {
            return tree[node];
        }
        int mid = (l + r) >> 1;
        if (qr <= mid) {
            return query(node << 1, l, mid, ql, qr);
        }
        if (ql > mid) {
            return query((node << 1) | 1, mid + 1, r, ql, qr);
        }
        Node leftRes = query(node << 1, l, mid, ql, qr);
        Node rightRes = query((node << 1) | 1, mid + 1, r, ql, qr);
        return merge(leftRes, rightRes, null);
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        N = scanner.nextInt();
        if (N == -1) return;
        M = scanner.nextInt();

        S = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            S[i] = scanner.nextInt();
        }

        tree = new Node[4 * N + 1];
        for (int i = 0; i < tree.length; i++) {
            tree[i] = new Node();
        }

        build(1, 1, N);

        PrintWriter out = new PrintWriter(System.out);

        for (int k = 0; k < M; k++) {
            int type = scanner.nextInt();
            if (type == 1) {
                int idx = scanner.nextInt();
                int val = scanner.nextInt();
                update(1, 1, N, idx, val);
            } else {
                int l = scanner.nextInt();
                int r = scanner.nextInt();
                Node res = query(1, 1, N, l, r);
                out.println(res.ans);
            }
        }

        out.flush();
    }
}
