public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte read() {
            if (head >= tail) {
                head = 0;
                try {
                    tail = in.read(buffer, 0, buffer.length);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() {
            byte c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') {
                    throw new RuntimeException();
                }
                res = res * 10 + c - '0';
                c = read();
            }
            return res;
        }
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static class Node {
        long ans;
        int prefSize;
        int suffSize;
        int[] prefGcd = new int[32];
        int[] prefCnt = new int[32];
        int[] suffGcd = new int[32];
        int[] suffCnt = new int[32];

        void setLeaf(int val) {
            prefSize = 1;
            prefGcd[0] = val;
            prefCnt[0] = 1;

            suffSize = 1;
            suffGcd[0] = val;
            suffCnt[0] = 1;

            ans = (val > 1) ? 1 : 0;
        }

        void copyFrom(Node o) {
            this.ans = o.ans;
            this.prefSize = o.prefSize;
            System.arraycopy(o.prefGcd, 0, this.prefGcd, 0, o.prefSize);
            System.arraycopy(o.prefCnt, 0, this.prefCnt, 0, o.prefSize);

            this.suffSize = o.suffSize;
            System.arraycopy(o.suffGcd, 0, this.suffGcd, 0, o.suffSize);
            System.arraycopy(o.suffCnt, 0, this.suffCnt, 0, o.suffSize);
        }
    }

    static void merge(Node a, Node b, Node res) {
        long cross = 0;
        for (int i = 0; i < a.suffSize; i++) {
            int g1 = a.suffGcd[i];
            int c1 = a.suffCnt[i];
            for (int j = 0; j < b.prefSize; j++) {
                if (gcd(g1, b.prefGcd[j]) > 1) {
                    cross += (long) c1 * b.prefCnt[j];
                }
            }
        }
        res.ans = a.ans + b.ans + cross;

        // Prefixes
        for (int i = 0; i < a.prefSize; i++) {
            res.prefGcd[i] = a.prefGcd[i];
            res.prefCnt[i] = a.prefCnt[i];
        }
        res.prefSize = a.prefSize;

        int totalA = a.prefGcd[a.prefSize - 1];
        for (int i = 0; i < b.prefSize; i++) {
            int g = gcd(totalA, b.prefGcd[i]);
            int c = b.prefCnt[i];
            if (g == res.prefGcd[res.prefSize - 1]) {
                res.prefCnt[res.prefSize - 1] += c;
            } else {
                res.prefGcd[res.prefSize] = g;
                res.prefCnt[res.prefSize] = c;
                res.prefSize++;
            }
        }

        // Suffixes
        for (int i = 0; i < b.suffSize; i++) {
            res.suffGcd[i] = b.suffGcd[i];
            res.suffCnt[i] = b.suffCnt[i];
        }
        res.suffSize = b.suffSize;

        int totalB = b.suffGcd[b.suffSize - 1];
        for (int i = 0; i < a.suffSize; i++) {
            int g = gcd(totalB, a.suffGcd[i]);
            int c = a.suffCnt[i];
            if (g == res.suffGcd[res.suffSize - 1]) {
                res.suffCnt[res.suffSize - 1] += c;
            } else {
                res.suffGcd[res.suffSize] = g;
                res.suffCnt[res.suffSize] = c;
                res.suffSize++;
            }
        }
    }

    static Node[] tree;
    static int[] S;

    static void build(int node, int l, int r) {
        tree[node] = new Node();
        if (l == r) {
            tree[node].setLeaf(S[l]);
            return;
        }
        int mid = (l + r) >>> 1;
        build(2 * node, l, mid);
        build(2 * node + 1, mid + 1, r);
        merge(tree[2 * node], tree[2 * node + 1], tree[node]);
    }

