            b = t;
        }
        return a;
    }

    static class Node {
        long ans;
        int prefSize;
        int suffSize;
        int[] prefGcd = new int[32];
        int[] prefCnt = new int[32];
        int[] suffGcd = new int[32];
        int[] suffCnt = new int[32];

        void setLeaf(int val) {
            prefSize = 1;
            prefGcd[0] = val;
            prefCnt[0] = 1;

            suffSize = 1;
            suffGcd[0] = val;
            suffCnt[0] = 1;

            ans = (val > 1) ? 1 : 0;
        }

        void copyFrom(Node o) {
            this.ans = o.ans;
            this.prefSize = o.prefSize;
            System.arraycopy(o.prefGcd, 0, this.prefGcd, 0, o.prefSize);
            System.arraycopy(o.prefCnt, 0, this.prefCnt, 0, o.prefSize);

            this.suffSize = o.suffSize;
            System.arraycopy(o.suffGcd, 0, this.suffGcd, 0, o.suffSize);
            System.arraycopy(o.suffCnt, 0, this.suffCnt, 0, o.suffSize);
        }
    }

    static void merge(Node a, Node b, Node res) {
        long cross = 0;
        for (int i = 0; i < a.suffSize; i++) {
            int g1 = a.suffGcd[i];
            int c1 = a.suffCnt[i];
            for (int j = 0; j < b.prefSize; j++) {
                if (gcd(g1, b.prefGcd[j]) > 1) {
                    cross += (long) c1 * b.prefCnt[j];
                }
            }
        }
        res.ans = a.ans + b.ans + cross;

        // Prefixes
        for (int i = 0; i < a.prefSize; i++) {
            res.prefGcd[i] = a.prefGcd[i];
            res.prefCnt[i] = a.prefCnt[i];
        }
        res.prefSize = a.prefSize;

        int totalA = a.prefGcd[a.prefSize - 1];
        for (int i = 0; i < b.prefSize; i++) {
            int g = gcd(totalA, b.prefGcd[i]);
            int c = b.prefCnt[i];
            if (g == res.prefGcd[res.prefSize - 1]) {
                res.prefCnt[res.prefSize - 1] += c;
            } else {
                res.prefGcd[res.prefSize] = g;
                res.prefCnt[res.prefSize] = c;
                res.prefSize++;
            }
        }

        // Suffixes
        for (int i = 0; i < b.suffSize; i++) {
            res.suffGcd[i] = b.suffGcd[i];
            res.suffCnt[i] = b.suffCnt[i];
        }
        res.suffSize = b.suffSize;

        int totalB = b.suffGcd[b.suffSize - 1];
        for (int i = 0; i < a.suffSize; i++) {
            int g = gcd(totalB, a.suffGcd[i]);
            int c = a.suffCnt[i];
            if (g == res.suffGcd[res.suffSize - 1]) {
                res.suffCnt[res.suffSize - 1] += c;
            } else {
                res.suffGcd[res.suffSize] = g;
                res.suffCnt[res.suffSize] = c;
                res.suffSize++;
            }
        }
    }

    static Node[] tree;
    static int[] S;

    static void build(int node, int l, int r) {
        tree[node] = new Node();
        if (l == r) {
            tree[node].setLeaf(S[l]);
            return;
        }
        int mid = (l + r) >>> 1;
        build(2 * node, l, mid);
        build(2 * node + 1, mid + 1, r);
        merge(tree[2 * node], tree[2 * node + 1], tree[node]);
    }

    static void update(int node, int l, int r, int idx, int val) {
        if (l == r) {
            tree[node].setLeaf(val);
            return;
        }
        int mid = (l + r) >>> 1;
        if (idx <= mid) {
            update(2 * node, l, mid, idx, val);
        } else {
            update(2 * node + 1, mid + 1, r, idx, val);
        }
        merge(tree[2 * node], tree[2 * node + 1], tree[node]);
    }

    static Node acc = new Node();
    static Node temp = new Node();
    static boolean hasAcc = false;

    static void query(int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) {
            if (!hasAcc) {
                acc.copyFrom(tree[node]);
                hasAcc = true;
            } else {
                merge(acc, tree[node], temp);
                acc.copyFrom(temp);
            }
            return;
        }
        int mid = (l + r) >>> 1;
        if (ql <= mid) {
            query(2 * node, l, mid, ql, qr);
        }
        if (qr > mid) {
            query(2 * node + 1, mid + 1, r, ql, qr);
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        int n = scanner.nextInt();
        if (n == -1) return;
        int m = scanner.nextInt();

        S = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            S[i] = scanner.nextInt();
        }

        tree = new Node[4 * n + 1];
        build(1, 1, n);

        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < m; i++) {
            int t = scanner.nextInt();
            if (t == 1) {
                int idx = scanner.nextInt();
                int val = scanner.nextInt();
                update(1, 1, n, idx, val);
            } else {
                int l = scanner.nextInt();
                int r = scanner.nextInt();
                hasAcc = false;
                query(1, 1, n, l, r);
                sb.append(acc.ans).append('\n');
            }
        }

        System.out.print(sb.toString());
    }
}
